import React, { useState } from 'react';

export default function Shipping({
  shippingAddress,
  onChange,
  onNext,
  onBack,
  submitLabel = 'Continue →',
  cancelLabel = '← Back',
  onSubmit,
  onCancel,
}) {
  const [errors, setErrors] = useState({});


   

 const validate = () => {
  const newErrors = {};

  if (!shippingAddress.firstName?.toString().trim()) {
    newErrors.firstName = 'First name is required';
  }
  if (!shippingAddress.lastName?.toString().trim()) {
    newErrors.lastName = 'Last name is required';
  }
  if (!shippingAddress.address?.toString().trim()) {
    newErrors.address = 'Address is required';
  }
  if (!shippingAddress.city?.toString().trim()) {
    newErrors.city = 'City is required';
  }
  if (!shippingAddress.state?.toString().trim()) {
    newErrors.state = 'State is required';
  }
  if (!shippingAddress.zip?.toString().trim()) {
    newErrors.zip = 'ZIP code is required';
  }

  setErrors(newErrors);
  return Object.keys(newErrors).length === 0;
};

   const addressLabel = [
    'Home',
    'Work',
    'Billing',
    'Shipping',
    'Parents Home',
    'other'
   ]

  const handleSubmit = () => {
    if (validate()) {
      (onSubmit || onNext)?.();
    }
  };

  const handleCancel = () => {
    (onCancel || onBack)?.();
  };

  return (
    <div className="card p-4 shadow-sm">
      <h4 className="mb-3">Shipping Address</h4>

      <div className="row mb-3">
        <div className="col-md-6">
          <label htmlFor="firstName" className="form-label">First Name</label>
          <input
            id="firstName"
            name="firstName"
            className={`form-control ${errors.firstName ? 'is-invalid' : ''}`}
            value={shippingAddress.firstName}
            onChange={onChange}
          />
          {errors.firstName && <div className="invalid-feedback">{errors.firstName}</div>}
        </div>
        <div className="col-md-6">
          <label htmlFor="lastName" className="form-label">Last Name</label>
          <input
            id="lastName"
            name="lastName"
            className={`form-control ${errors.lastName ? 'is-invalid' : ''}`}
            value={shippingAddress.lastName}
            onChange={onChange}
          />
          {errors.lastName && <div className="invalid-feedback">{errors.lastName}</div>}
        </div>
      </div>

      <div className="mb-3">
        <label htmlFor="address" className="form-label">Address</label>
        <input
          id="address"
          name="address"
          className={`form-control ${errors.address ? 'is-invalid' : ''}`}
          value={shippingAddress.address}
          onChange={onChange}
        />
        {errors.address && <div className="invalid-feedback">{errors.address}</div>}
      </div>

      <div className="mb-3">
        <label htmlFor="apartment" className="form-label">Apartment, suite, etc. (optional)</label>
        <input
          id="apartment"
          name="apartment"
          className="form-control"
          value={shippingAddress.apartment}
          onChange={onChange}
        />
      </div>

      <div className="row mb-3">
        <div className="col-md-4">
          <label htmlFor="city" className="form-label">City</label>
          <input
            id="city"
            name="city"
            className={`form-control ${errors.city ? 'is-invalid' : ''}`}
            value={shippingAddress.city}
            onChange={onChange}
          />
          {errors.city && <div className="invalid-feedback">{errors.city}</div>}
        </div>
        <div className="col-md-4">
          <label htmlFor="state" className="form-label">State</label>
          <input
            id="state"
            name="state"
            className={`form-control ${errors.state ? 'is-invalid' : ''}`}
            value={shippingAddress.state}
            onChange={onChange}
          />
          {errors.state && <div className="invalid-feedback">{errors.state}</div>}
        </div>
        <div className="col-md-4">
          <label htmlFor="zip" className="form-label">ZIP Code</label>
          <input
            id="zip"
            name="zip"
            className={`form-control ${errors.zip ? 'is-invalid' : ''}`}
            value={shippingAddress.zip}
            onChange={onChange}
          />
          {errors.zip && <div className="invalid-feedback">{errors.zip}</div>}
        </div>
      </div>

      <div className="row mb-3">
  <div className="col-md-6">
    <label htmlFor="phone" className="form-label">Phone (optional)</label>
    <input
      id="phone"
      name="phone"
      className="form-control"
      value={shippingAddress.phone}
      onChange={onChange}
    />
  </div>

      <div className="col-md-6">
        <label htmlFor="label" className="form-label">Label</label>
        <select
          id="label"
          name="label"
          className="form-select"
          value={shippingAddress.label}
          onChange={onChange}
        >
          {addressLabel.map(option => (
            <option key={option} value={option}>{option}</option>
          ))}
        </select>
      </div>
    </div>

      <div className="d-flex justify-content-between">
        <button type="button" className="btn btn-secondary" onClick={handleCancel}>
          {cancelLabel}
        </button>
        <button type="button" className="btn btn-primary" onClick={handleSubmit}>
          {submitLabel}
        </button>
      </div>
    </div>
  );
}
