import React from 'react';
import config from '../../script/config';
import { Card, Row, Col, Button, Badge, ListGroup } from 'react-bootstrap';

export default function MyOrders({allOrders}) {
 
  const statusVariant = {
    Delivered: 'success',
    'In Transit': 'warning',
    Cancelled: 'danger',
    Processing: 'info',
  };

 
const totalPriceForOrder = (order) => {
  return order.items.reduce((sum, item) => sum + item.price * item.qty, 0);
};


  return (
    <div style={{ maxWidth: 750, margin: '2rem auto' }}>
      <h4 className="mb-4 fw-bold">My Orders ({allOrders.length})</h4>

      {allOrders.map((order, index) => (
        <Card key={order.id || index} className="mb-3 shadow-sm rounded-3 border">
          <Card.Body>
            <Row>
              <Col md={8}>
                <div className="d-flex justify-content-between align-items-center mb-2">
                  <h6 className="fw-semibold mb-0">Order ID: {order.id}</h6>
                  <Badge
                    bg={statusVariant[order.status] || 'secondary'}
                    className="text-uppercase fw-semibold"
                    style={{ letterSpacing: '0.05em' }}
                  >
                    {order.status}
                  </Badge>
                </div>
                <p className="text-muted mb-1" style={{ fontSize: '0.9rem' }}>
                  Order Date: {new Date(order.date).toLocaleDateString()}
                </p>

                <ListGroup variant="flush" className="mb-2" style={{ maxHeight: 120, overflowY: 'auto' }}>
                  {order.items.map((item, idx) => (
                    <ListGroup.Item key={`${order.id}-${item.name}-${idx}`} className="px-0 py-1 d-flex justify-content-between align-items-center">
                      <span>
                        {item.name} <small className="text-muted">x{item.qty}</small>
                      </span>
                      <strong>{config.rupeeSymbol}{(item.price * item.qty).toLocaleString('en-IN')}</strong>
                    </ListGroup.Item>
                  ))}
                </ListGroup>

                <p className="mb-0" style={{ fontSize: '0.9rem' }}>
                  <strong>Delivery Address:</strong> {order.deliveryAddress}
                </p>
              </Col>

              <Col
                md={4}
                className="d-flex flex-column justify-content-center align-items-end gap-2"
              >
                <h5 className="mb-3 text-primary">{config.rupeeSymbol}{totalPriceForOrder(order).toLocaleString('en-IN')}</h5>

                <Button
                  variant="outline-primary"
                  size="sm"
                  className="rounded-pill w-100"
                >
                  View Details
                </Button>
                <Button
                  variant="outline-secondary"
                  size="sm"
                  className="rounded-pill w-100"
                >
                  Track Order
                </Button>
              </Col>
            </Row>
          </Card.Body>
        </Card>
      ))}
    </div>
  );
}
