export function validateCoupon(code, coupons) {
  const normalized = code.trim().toUpperCase();
  
  if (!coupons.includes(normalized)) {
    return { valid: false, amount: 0, code: '' };
  }
  
  const match = normalized.match(/\d+/);
  const amount = match ? parseInt(match[0], 10) : 0;

  if (amount > 0) {
    return { valid: true, amount, code: normalized };
  }
  
  return { valid: false, amount: 0, code: '' };
}