import React from "react";
import { QRCodeCanvas } from "qrcode.react";
import config from "../../script/config";

const QRCodeComponent = ({ id, money, size }) => {

    const upi = `upi://pay?pa=${id}&pn=Merchant&am=${money}&cu=INR`
  return (
        <div style={{ 
                textAlign: "center", 
                display: "flex", 
                flexDirection: "column", 
                alignItems: "center", 
                gap: "6px"  // smaller gap
                }}>
                <h3 style={{ 
                    fontSize: "1rem", 
                    marginBottom: "4px",
                    marginTop: -10
                }}>
                    Scan to Pay {config.rupeeSymbol} {money.toLocaleString('en-IN')}
                </h3>
                <QRCodeCanvas value={upi} size={size} />
        </div>
  );
};

export default QRCodeComponent;