import React, { useState } from 'react';
import { toast } from 'react-toastify';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Eye, EyeSlashFill } from 'react-bootstrap-icons';
import { InputGroup, Form, Button, Spinner } from 'react-bootstrap';
import config from '../../script//config'; // Adjust the path as necessary
import { otpEmailContent } from '../../script/htmlContent'; // Assuming you have a separate file for email content
import { useNavigate } from 'react-router-dom';


export default function ForgotPassword() {
  const [step, setStep] = useState(1); // 1=email, 2=otp, 3=reset pwd
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState();
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  // Toggle password visibility
  const togglePasswordVisibility = () => setShowPassword(!showPassword);
  const toggleConfirmPasswordVisibility = () => setShowConfirmPassword(!showConfirmPassword);

  // Step 1: Send OTP to email
  
  const handleSendOtp = async (e) => {
     e.preventDefault();
  setLoading(true);

  if (!email) {
    toast.error('Please enter your email.');
    setLoading(false);
    return;
  }

    const otp_new = Math.floor(100000 + Math.random() * 900000).toString(); 
    setGeneratedOtp(otp_new);
    console.log('Generated OTP:', otp_new); // For debugging, remove in production
    try 
    {
        const formData = new URLSearchParams();
        formData.append('Action', 'email');
        formData.append('Type', 'otp');
        formData.append('Receiver', email);
        formData.append('Subject', `Forgot Password`);
        formData.append('Body', otpEmailContent(otp_new));
        
        const res = await fetch(config.apiEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: formData.toString(),
    });

      const data = await res.json();
      if (data.success) 
    {
        setStep(2);
        toast.success(data.message || 'OTP sent to your email! Please check your inbox.');
      } 
      else 
      {
        toast.error(data.message || 'Failed to send OTP.');
      }
    } 
    catch (err) {
      toast.error('Error sending OTP. Try again.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };


  // Step 2: Verify OTP
  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    if (!otp) {
      toast.error('Please enter the OTP.');
      return;
    }

    try 
    {
       
        if(otp.toString() === generatedOtp?.toString()) 
        {
            toast.success('OTP verified. You can reset your password now.');
            setStep(3);
        }
        else 
        {
            toast.error(otp.message || 'Invalid OTP. Please try again.');
        }
    } 
    catch (err) 
    {
      toast.error('Error verifying OTP. Try again.');
      console.error(err);
    } 
    finally 
    {
      setLoading(false);
    }
  };

  // Step 3: Reset password
  const handleResetPassword = async (e) => {
    e.preventDefault();
    if (!password || !confirmPassword) {
      toast.error('Please fill all password fields.');
      return;
    }
    if (password !== confirmPassword) {
      toast.error('Passwords do not match.');
      return;
    }
    setLoading(true);
    try 
    {
        const formData = new URLSearchParams();
        formData.append('Action', 'resetpassword');
        formData.append('Email', email);
        formData.append('Password', password);

        console.log(formData.toString()); // For debugging, remove in production
        console.log("API Endpoint:", config.apiEndpoint);
        const res = await fetch(config.apiEndpoint, { 
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: formData.toString(),
      });

      const data = await res.json();
      if (data.success) 
    {
        toast.success(data.message || 'Password reset successful! You can now log in with your new password.');
        setStep(1);
        setEmail('');
        setOtp('');
        setPassword('');
        setConfirmPassword('');
        navigate('/login'); // Redirect to login page after successful reset
      } 
      else 
      {
        toast.error(data.message || 'Failed to reset password.');
      }
    } 
    catch (err) 
    {
      toast.error('Error resetting password. Try again.');
      console.error(err);
    } 
    finally 
    {
      setLoading(false);
    }
  };

  return (
    <div className="container" style={{ maxWidth: 650, marginTop: '3rem' }}>
      <div className="card shadow-sm">
        <div className="card-body">
          <h3 className="card-title text-center mb-4">Forgot Password</h3>

          {step === 1 && (
            <form onSubmit={handleSendOtp}>
              <Form.Group className="mb-3" controlId="forgotEmail">
                <Form.Label>Email address</Form.Label>
                <Form.Control
                  type="email"
                  placeholder="Enter your registered email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  disabled={loading}
                />
              </Form.Group>

              <Button variant="primary" type="submit" disabled={loading} className="w-100">
                {loading ? <Spinner animation="border" size="sm" /> : 'Send OTP'}
              </Button>
            </form>
          )}

          {step === 2 && (
            <form onSubmit={handleVerifyOtp}>
              <Form.Group className="mb-3" controlId="otpInput">
                <Form.Label>Enter OTP</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Enter the OTP sent to your email"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                  required
                  disabled={loading}
                />
              </Form.Group>

              <Button variant="primary" type="submit" disabled={loading} className="w-100 mb-2">
                {loading ? <Spinner animation="border" size="sm" /> : 'Verify OTP'}
              </Button>

              <Button
                variant="link"
                onClick={() => setStep(1)}
                disabled={loading}
                className="w-100"
              >
                Back to Email
              </Button>
            </form>
          )}

          {step === 3 && (
            <form onSubmit={handleResetPassword}>
              <Form.Group className="mb-3" controlId="newPassword">
                <Form.Label>New Password</Form.Label>
                <InputGroup>
                  <Form.Control
                    type={showPassword ? 'text' : 'password'}
                    placeholder="Enter new password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <InputGroup.Text
                    onClick={togglePasswordVisibility}
                    style={{ cursor: 'pointer' }}
                  >
                    {showPassword ? <EyeSlashFill /> : <Eye />}
                  </InputGroup.Text>
                </InputGroup>
              </Form.Group>

              <Form.Group className="mb-3" controlId="confirmPassword">
                <Form.Label>Confirm Password</Form.Label>
                <InputGroup>
                  <Form.Control
                    type={showConfirmPassword ? 'text' : 'password'}
                    placeholder="Confirm new password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required
                    disabled={loading}
                  />
                  <InputGroup.Text
                    onClick={toggleConfirmPasswordVisibility}
                    style={{ cursor: 'pointer' }}
                  >
                    {showConfirmPassword ? <EyeSlashFill /> : <Eye />}
                  </InputGroup.Text>
                </InputGroup>
              </Form.Group>

              <Button variant="primary" type="submit" disabled={loading} className="w-100">
                {loading ? <Spinner animation="border" size="sm" /> : 'Reset Password'}
              </Button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
