import React, { useState, useContext, useEffect } from 'react';
import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import { HashRouter, Routes, Route } from 'react-router-dom';
import LoginForm from './assets/modules/login/Login';
import RegisterForm from './assets/modules/register/RegisterForm';
import Home from './assets/modules/home/Home';
import ProductDescription from './assets/modules/product/form/ProductDescription';
import Layout from './assets/common/Layout';
import Checkout from './assets/modules/checkout/Checkout';
import CartContainer from './assets/modules/cart/CartContainer';
import InvoiceApp from './assets/modules/invoice/InvoiceApp'
import logo from "../src/assets/modules/images/gprn_logo_big.png"

import ConfigContext from './assets/script/ConfigContext';
import UserDashboard from './assets/modules/user/UserDashboard';
import { validateToken } from './assets/script/AutoLogin';
import { UserHistory } from './assets/script/UserHistory';
import ForgotPassword from './assets/modules/login/ForgotPassword';

//[...prevItems] => is a new array with all the same items copied from prevItems.

function App() {

  const config = useContext(ConfigContext);

  //All product details added to cart
  const [cartItems, setCartItems] = useState([]);

  const [productOptions, setProductOptions] = useState({
    style: null,
    size: null,
    length: null,
  });


  const [shippingCharge, setShippingCharge] = useState(config.shippingCharge); //Shipping charge
  const [gstAmount, setGstAmount] = useState(0); //GST rate
  const [promoCodeDiscount, setPromoCodeDiscount] = useState(0); //Promo code discount


  // User state to manage user information
  const [user, setUser] = useState(); //user entire information
  const [isLoggedIn, setIsLoggedIn] = useState(false); //login status
  const [savedAddresses, setSavedAddresses] = useState([]); 
  
  //user saved addresses
  const [allOrders, setAllOrders] = useState([]); //user all orders addresses

  const [customerInformation, setCustomerInformation] = useState({
    email: '',
    firstName: '',
    lastName: '',
    address: '',
    apartment: '',
    city: '',
    country: 'India',
    state: '',
    zip: '',
    phone: '',
    label:''
  });

  /** ADD TO CART :
  * This to add the items in the cart and can be shared throughout the application
  */
  const addToCart = (product) => {
    setCartItems(prevItems => {
      const exist = prevItems.find(item => item.id === product.id);
      if (exist) 
        {
            return prevItems.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item );
        } 
        else 
        {
            return [...prevItems, { ...product, quantity: product.quantity || 1 }];
        }
    });
  };


  /** REDUCE QUANTITY OF ITEM : 
  * This is to remove quantity or remove product if quantity is < 1
  */
  const removeFromCart = (product) => {
    setCartItems(prevItems => {
      return prevItems.map(item => {
        if (item.id === product.id) {
          if (item.quantity === 1) {
            return item;
          }
          return { ...item, quantity: item.quantity - 1 };
        }
        return item;
      });
    });

  };

  /** DELETE ITEM FROM CART : 
  * This is to delete product completely from the cart
  */
  const deleteFromCart = (product) => {
    setCartItems(prevItems => prevItems.filter(item => item.id !== product.id));
  };

  const item = cartItems.map(item => ({
  description: item.title,
  quantity: item.quantity,
  price: item.price,
}));

useEffect(() => {
  async function checkToken() {
    await validateToken(config.apiEndpoint, setUser, setIsLoggedIn);
  }
  checkToken();
}, [config.apiEndpoint]);


useEffect(() => {
  async function fetchUserHistory() {
    if (isLoggedIn && user) {
      await UserHistory(config.apiEndpoint, user.email, setSavedAddresses, setAllOrders);
    }
  }
  fetchUserHistory();
}, [isLoggedIn, user,config.apiEndpoint]); // Runs when login state or user changes

  //****************************************************************
  // DELETE_FROM_CART
  //-----------------
  //
  // This is to delete product completely from the cart
  //****************************************************************
const Invoice = {
  company: {
    name: "GPRN SOFTWARE",
    logoUrl:logo,
    address: "Near Phoenix Mall, Bangalore, Karnataka",
    email: "contact@mrsinghmart.com",
    phone: "+91 809 351 2506",
  },

  customer: {
    name: `${customerInformation.firstName} ${customerInformation.lastName}`,

    address: `${customerInformation.address}, 
              ${customerInformation.apartment} 
              ${customerInformation.city}, 
              ${customerInformation.state},
              ${customerInformation.zip}`,
    email: customerInformation.email,

    phone: customerInformation.mobile,
  },
  
  invoiceNumber: "INV-1001",
  invoiceDate: "2025-05-17",
  dueDate: "2025-06-01",

  items: item,

  notes: "Thank you for shopping with us!",
  terms: "Payment due within 15 days.",
};



return (
  <div className="App-bg min-vh-100 d-flex flex-column">
    <HashRouter>
      <Routes>
        {/* Common layout for all pages */}
        <Route path="/" element={<Layout 
          cartItems={cartItems}
          addToCart={addToCart}
          removeFromCart={removeFromCart}
          deleteFromCart={deleteFromCart}
          user={user}
          isLoggedIn = {isLoggedIn}
          setIsLoggedIn = {setIsLoggedIn}
        />}>
          {/* Nested routes inside Layout */}
          <Route index element={<Home />} />
          <Route path="home" element={<Home />} />
          <Route path="forgot" element={<ForgotPassword />} />
          <Route path="login" element={<LoginForm setUser={setUser} setIsLoggedIn={setIsLoggedIn}/>} />
          <Route path="registration" element={<RegisterForm />} />
          <Route path="invoice" element={<InvoiceApp 
                invoiceData={Invoice}
                shippingCharge={shippingCharge}
                gstAmount={gstAmount}
                promoCodeDiscount={promoCodeDiscount}
                />
          } />

          <Route path="checkout" element={
           <Checkout 
                  cartItems={cartItems}
                  shippingCharge={shippingCharge}
                  setShippingCharge={setShippingCharge}
                  setCustomerInformation={setCustomerInformation}
                  setGstAmount={setGstAmount}
                  gstAmount={gstAmount}

                  promoCodeDiscount={promoCodeDiscount}
                  setPromoCodeDiscount={setPromoCodeDiscount}
                />
            } />

          <Route path="products/:id" element={
              <ProductDescription 
                cartItems={cartItems}
                addToCart={addToCart}
                removeFromCart={removeFromCart}
                deleteFromCart={deleteFromCart}
                productOptions = {productOptions}
                setProductOptions = {setProductOptions}

              />
            } />

          <Route path="cart" element={<CartContainer 
            cartItems={cartItems}
            addToCart={addToCart}
            removeFromCart={removeFromCart}
            deleteFromCart={deleteFromCart}
          />} />

          <Route path="dashboard" element={<UserDashboard 
            user={user} 
            setIsLoggedIn={setIsLoggedIn}
            savedAddresses={savedAddresses}
            setSavedAddresses={setSavedAddresses}
            allOrders ={allOrders}
            />} />

        </Route>
      </Routes>
    </HashRouter>
  </div>
);
}

export default App;
