import React from "react";
import config from "../../script/config";

export default function OrderSummary({
  cartItems,
  shippingCost,
  discountCode,
  onDiscountCodeChange,
  onApplyDiscount,
  totalAmount,
  gstAmount,
  coupons = [],
  appliedCoupon,
  onRemoveCoupon,
  promoCodeDiscount = 0,
}) {
  const calculateSubtotal = () =>
    cartItems.reduce((sum, item) => sum + item.quantity * item.price, 0);

  return (
    <div className="card shadow-sm border-0">
      <div className="card-body">
        <h5 className="fw-bold mb-4">Order Summary</h5>
        <ul className="list-unstyled">
          {cartItems.map((item) => (
            <li key={item.title} className="d-flex justify-content-between mb-2">
              <span>{item.quantity} x {item.title}</span>
              <span>{config.rupeeSymbol}{(item.quantity * item.price).toLocaleString('en-IN')}</span>
            </li>
          ))}
        </ul>
        <hr />
        <div className="d-flex justify-content-between">
          <span>Subtotal</span>
          <span>{config.rupeeSymbol}{calculateSubtotal().toLocaleString('en-IN')}</span>
        </div>
        <div className="d-flex justify-content-between">
          <span>Shipping</span>
          <span>{config.rupeeSymbol}{shippingCost.toLocaleString('en-IN')}</span>
        </div>
        <div className="d-flex justify-content-between">
          <span>Gst ({config.gstRate}%)</span>
          <span>{config.rupeeSymbol} {gstAmount.toLocaleString('en-IN')}</span>
        </div>

        {/* Discount display */}
        {promoCodeDiscount > 0 && (
          <div className="d-flex justify-content-between text-success fw-bold">
            <span>Discount</span>
            <span>- {config.rupeeSymbol}{promoCodeDiscount.toLocaleString('en-IN')}</span>
          </div>
        )}

        {/* Coupon Dropdown */}
        <div className="mb-3 mt-3">
          <label htmlFor="discountCode" className="form-label">Select Discount Code</label>
          <div className="input-group">
            <select
              className="form-select"
              id="discountCode"
              value={discountCode}
              onChange={onDiscountCodeChange}
              disabled={!!appliedCoupon}
            >
              <option value="">-- Select a coupon --</option>
              {coupons.map((code, index) => (
                <option key={index} value={code}>
                  {code} - {config.rupeeSymbol}{code.match(/\d+/)?.[0] || 0} off
                </option>
              ))}
            </select>
            <button
              className="btn btn-outline-secondary"
              type="button"
              onClick={onApplyDiscount}
              disabled={!discountCode || !!appliedCoupon}
            >
              Apply
            </button>
          </div>

          {appliedCoupon && (
            <div className="mt-2 d-flex justify-content-between align-items-center">
              <span className="text-success">Applied: {appliedCoupon}</span>
              <button
                className="btn btn-sm btn-outline-danger"
                onClick={onRemoveCoupon}
              >
                Remove
              </button>
            </div>
          )}
        </div>

        <hr />
        <div className="d-flex justify-content-between fw-bold">
          <span>Total</span>
          <span>{config.rupeeSymbol} {totalAmount.toLocaleString('en-IN')}</span>
        </div>
        <div className="mt-3 d-flex gap-2">
          <img
            src="https://placehold.co/80x80/cccccc/ffffff?text=Secure"
            alt="Secure"
          />
          <img
            src="https://placehold.co/80x80/cccccc/ffffff?text=Trusted"
            alt="Trusted"
          />
        </div>
      </div>
    </div>
  );
}
