import React, {useState} from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faHome,faUser,faShoppingCart,faSearch,faUserCircle,faSignOutAlt } from '@fortawesome/free-solid-svg-icons';
import 'bootstrap/dist/css/bootstrap.min.css';
import logo from '../images/mrsingh.png';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import * as bootstrap from 'bootstrap';
import { logout } from '../../script/Logout';
import config from '../../script/config';
import LoadingScreen from '../loadingScreen/LoadingScreen';

/** DISABLE SIDE MENU : 
 * This is to close the side nav menu bar, which is opening base onm screen size
*/
const closeOffcanvas = () => {
  const offcanvasEl = document.getElementById('offcanvasMenu');
  if (offcanvasEl) {
    let bsOffcanvas = bootstrap.Offcanvas.getInstance(offcanvasEl);
    if (!bsOffcanvas) {
      bsOffcanvas = new bootstrap.Offcanvas(offcanvasEl);
    }
    bsOffcanvas.hide();
    document.body.classList.remove('offcanvas-backdrop', 'show', 'modal-open','fade');
    const backdrop = document.querySelector('.offcanvas-backdrop');
    if (backdrop) backdrop.remove();
  }
};

function Navbar({ cartItems, user, isLoggedIn, setIsLoggedIn}) {
  const totalItems = cartItems.reduce((total, item) => total + item.quantity, 0);
  const navigate = useNavigate();

  const [isLoading, setIsLoading] = useState(false);

  /** NAVIGATE TO LOGIN : 
  * This to handle navigation to login screen
  */
  const handleLogin = () => {
   setTimeout(()=> {
      navigate('/login');
   }, 300) 
    closeOffcanvas();
  };

  /** NAVIGATE TO DASHBOARD
  * This to handle navigation to dashboard [User Information, Addresses, My Order]
  */
  const handleDashboard = () => {
   setTimeout(()=> {
      navigate('/dashboard');
   }, 300) 
    closeOffcanvas();
  };

  /** NAVIGATE TO CART : 
  * This to handle navigation to display cart
  */
  const handleCart = () => {
    navigate('/cart');
    closeOffcanvas();
  };

  /** NAVIGATE TO SEARCH BAR
  * This to handle navigation to search operation
  */
  const handleSearch = () => {
    toast.info('Search feature is not implemented yet.');
    closeOffcanvas();
  };

  /** NAVIGATE TO HOME
  * This to handle navigation to home screen
  */
  const handleHome = () => {
    navigate('/home');
    closeOffcanvas();
  };

  /** NAVIGATE TO HOME
  * This to handle navigation to home screen
  */
  const handleLogout = async () => {
    navigate('/home');
    await logout(setIsLoggedIn, config.apiEndpoint, toast, navigate, setIsLoading)
    closeOffcanvas();
  };

 if (isLoading) {
  return <LoadingScreen message="Logging out..." />;
}

  return (
    <nav className="navbar navbar-dark bg-dark">
      <div className="container-fluid">
        <img src={logo} alt="MR Singh Mart Logo" height={40} width={40} className="me-2" />

        <button
          className="navbar-toggler d-lg-none"
          type="button"
          data-bs-toggle="offcanvas"
          data-bs-target="#offcanvasMenu"
          aria-controls="offcanvasMenu"
          aria-label="Toggle menu"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div className="d-none d-lg-flex ms-auto">
          <ul className="navbar-nav flex-row align-items-center gap-3">
            <li className="nav-item">
              <button className="nav-link d-flex align-items-center" onClick={handleHome}>
                <FontAwesomeIcon icon={faHome} className="me-1" size="lg" />
                Home
              </button>
            </li>

            {isLoggedIn ? (
              <li className="nav-item dropdown">
                <button
                  className="nav-link dropdown-toggle d-flex align-items-center"
                  onClick={handleDashboard}
                >
                  <FontAwesomeIcon icon={faUser} className="me-1" size="lg" />
                  {user.name}
                </button>
              </li>
            ) : (
              <li className="nav-item">
                <button className="nav-link d-flex align-items-center" onClick={handleLogin}>
                  <FontAwesomeIcon icon={faUser} className="me-1" size="lg" />
                  Login
                </button>
              </li>
            )}

            <li className="nav-item">
              <button className="nav-link d-flex align-items-center" onClick={handleCart}>
                <div className="position-relative">
                  <FontAwesomeIcon icon={faShoppingCart} className="me-1" size="lg" />
                  {totalItems > 0 && (
                    <span
                      className="position-absolute top-0 start-100 translate-middle bg-danger text-white fw-bold"
                      style={{
                        borderRadius: '12px',
                        fontSize: '0.75rem',
                        padding: '2px 6px',
                        lineHeight: '1',
                      }}
                    >
                      {totalItems}
                    </span>
                  )}
                </div>
                <span className="ms-1">Cart</span>
              </button>
            </li>

            <li className="nav-item">
              <button className="nav-link d-flex align-items-center" onClick={handleSearch}>
                <FontAwesomeIcon icon={faSearch} className="me-1" size="lg" />
                Search
              </button>
            </li>
          </ul>
        </div>

        {/* Offcanvas for small screens */}
        <div
          className="offcanvas offcanvas-start bg-dark text-light"
          tabIndex="-1"
          id="offcanvasMenu"
          aria-labelledby="offcanvasMenuLabel"
          style={{
            backgroundColor: '#212529',
            color: '#f8f9fa',
            borderRight: '1px solid rgb(4, 54, 104)',
          }}
        >
          <div className="offcanvas-header">
            <h5 className="offcanvas-title" id="offcanvasMenuLabel">Menu</h5>
            <button
              type="button"
              className="btn-close btn-close-white"
              data-bs-dismiss="offcanvas"
              aria-label="Close"
            ></button>
          </div>
          <div className="offcanvas-body">
            <ul className="navbar-nav">

              {isLoggedIn ? (
                <>
                  <li className="nav-item mb-2">
                    <span className="nav-link disabled">
                      Hello, {user.name}
                    </span>
                    <button className="nav-link" onClick={handleDashboard}>
                    <FontAwesomeIcon icon={faUserCircle} className="me-2" />
                    My Account
                  </button>
                  </li>
                 
                </>
              ) : (
                <li className="nav-item mb-2">
                  <button className="nav-link" onClick={handleLogin}>
                    <FontAwesomeIcon icon={faUser} className="me-2" />
                    Login
                  </button>
                </li>
              )}
              <li className="nav-item mb-2">
                <button className="nav-link" onClick={handleHome}>
                  <FontAwesomeIcon icon={faHome} className="me-2" />
                  Home
                </button>
              </li>

              <li className="nav-item">
              <button className="nav-link d-flex align-items-center" onClick={handleCart}>
                <div className="position-relative">
                  <FontAwesomeIcon icon={faShoppingCart} className="me-1" size="lg" />
                  {totalItems > 0 && (
                    <span
                      className="position-absolute top-0 start-100 translate-middle bg-danger text-white fw-bold"
                      style={{
                        borderRadius: '12px',
                        fontSize: '0.75rem',
                        padding: '2px 6px',
                        lineHeight: '1',
                      }}
                    >
                      {totalItems}
                    </span>
                  )}
                </div>
                <span className="ms-1">Cart</span>
              </button>
            </li>

              <li className="nav-item">
                <button className="nav-link" onClick={handleSearch}>
                  <FontAwesomeIcon icon={faSearch} className="me-2" />
                  Search
                </button>
              </li>

             { isLoggedIn && ( <li className="nav-item">
                <button className="nav-link" onClick={handleLogout}>
                  <FontAwesomeIcon icon={faSignOutAlt} className="me-2" />
                  Logout
                </button>
              </li>)
            }

            </ul>
          </div>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
