import { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import 'bootstrap/dist/css/bootstrap.min.css';
import config from '../../script/config';
import { useNavigate } from 'react-router-dom';
import { Eye, EyeSlashFill } from 'react-bootstrap-icons';
import { InputGroup, Form } from 'react-bootstrap';
import LoadingScreen from '../loadingScreen/LoadingScreen';
import { validateToken } from '../../script/AutoLogin';
import {  setCookie } from '../../script/cookies';

function LoginForm({ setUser , setIsLoggedIn}) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsSubmitting] = useState(false);


  const navigate = useNavigate();

  /** HIDE/SHOW PWD
   * This is to hide / show password based on user selection
  */
  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };


  /** AUTO LOGIN
   * This is to auto login based on token
  */
  useEffect(() => {
      validateToken(config.apiEndpoint, setUser, setIsLoggedIn);//AUTO LOGIN 
  }, [navigate, setUser, setIsLoggedIn]);


  /** LOGIN : 
   * This is login using id and password
  */
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const formData = new URLSearchParams();
      formData.append('Action', 'login');
      formData.append('Name', username);
      formData.append('Email', username);
      formData.append('Password', password);

      const response = await fetch(config.apiEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: formData.toString(),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (data.success && data.data) {
        const { token, user } = data.data;

        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));

        setCookie('shop-token', token); // Set token in cookie

        setUser(user);
        setIsLoggedIn(true);

        toast.success(data.message || 'Login successful!');
        navigate('/home');
      } else {
        toast.error(data.message || 'Login failed. Please try again.');
        console.error('Login failed:', data);
      }
    } catch (error) {
      toast.error(error.message || 'An error occurred. Please try again.');
      console.error('Error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="container">
      {isLoading && <LoadingScreen message="Logging in..." />}
      <div className="row justify-content-center">
        <div className="col-12 col-md-8 col-lg-6">
          <div className="card mt-5">
            <div className="card-body">
              <h2 className="card-title text-center mb-4">Login</h2>
              <form className="login-form" onSubmit={handleSubmit}>
                <div className="form-group mb-2">
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    name="email"
                    placeholder="Email Address *"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                  />
                </div>
                <div className="form-group mb-2">
                  <InputGroup>
                    <Form.Control
                      type={showPassword ? 'text' : 'password'}
                      id="password"
                      name="password"
                      placeholder="Password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                    />
                    <InputGroup.Text
                      onClick={togglePasswordVisibility}
                      style={{ cursor: 'pointer' }}
                    >
                      {showPassword ? <EyeSlashFill /> : <Eye />}
                    </InputGroup.Text>
                  </InputGroup>
                </div>
                <div className="form-group d-flex justify-content-between align-items-center">
                  <div className="form-check mb-2">
                    <input
                      type="checkbox"
                      className="form-check-input"
                      id="remember"
                      name="remember"
                    />
                    <label className="form-check-label" htmlFor="remember">
                      Remember me
                    </label>
                  </div>
                  <a href="#/forgot" className="text-muted">
                    Forgot your password?
                  </a>
                </div>
                <hr className="my-4" />
                <div className="d-flex justify-content-center gap-2">
                  <button type="submit" className="btn btn-primary mr-2" disabled={isLoading}>
                    Submit
                  </button>
                  <a href="#/registration" className="btn btn-outline-secondary">
                    Register
                  </a>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default LoginForm;
