import React from 'react';

export default function Banner({ promoCode, discountAmount, rupeeSymbol }) {
  return (
    <div className="discount-banner text-white py-2 px-3 position-relative overflow-hidden">
      <div className="scrolling-text fw-semibold">
        Use promo code <strong>{promoCode}</strong> at checkout to SAVE {rupeeSymbol}{discountAmount} and enjoy <u>Free Shipping</u>. Offer valid for a limited time only.
      </div>

      <style jsx>{`
        .discount-banner {
          background: linear-gradient(90deg, #2c3e50, #4ca1af);
          font-size: 1rem;
          white-space: nowrap;
          letter-spacing: 0.5px;
          border-radius: 5px;
        }

        .scrolling-text {
          display: inline-block;
          animation: scroll-left 25s linear infinite;
        }

        .discount-banner:hover .scrolling-text {
          animation-play-state: paused;
        }

        @keyframes scroll-left {
          0% {
            transform: translateX(100%);
          }
          100% {
            transform: translateX(-100%);
          }
        }

        @media (max-width: 768px) {
          .discount-banner {
            font-size: 0.9rem;
            padding: 0.5rem 1rem;
          }
        }
      `}</style>
    </div>
  );
}