import React, { useEffect, useState } from 'react';
import { Card, Row, Col, Image, Button, Form } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import config from '../../script/config';
import LoadingScreen from '../loadingScreen/LoadingScreen';
import { logout } from '../../script/Logout';

export default function Profile({ user: initialUser, setIsLoggedIn }) {
  const [user, setUser] = useState(initialUser || null);
  const [editMode, setEditMode] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', mobile: '' });
  const [previewImage, setPreviewImage] = useState(null);
  const [rawFile, setRawFile] = useState(null); // needed to send imageBase64
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (!initialUser) {
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        try {
          const parsed = JSON.parse(storedUser);
          setUser(parsed);
          setFormData({
            name: parsed.name,
            email: parsed.email,
            mobile: parsed.mobile || '',
          });
          setPreviewImage(parsed.image || config.defaultProfileImage);
        } catch (error) {
          console.error('Failed to parse user from localStorage', error);
        }
      }
    } else {
      setFormData({
        name: initialUser.name,
        email: initialUser.email,
        mobile: initialUser.mobile || '',
      });
      setPreviewImage(initialUser.image || config.defaultProfileImage);
    }
  }, [initialUser]);

  const handleLogout = async () => {
    await logout(setIsLoggedIn, config.apiEndpoint, toast, navigate, setIsLoading);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setRawFile(file); 
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewImage(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    if (!user) return;
    setIsLoading(true);

    const payload = new URLSearchParams();
    payload.append('Action', "profile");
    payload.append('email', user.email);
    payload.append('name', formData.name);
    payload.append('mobile', formData.mobile);

    if (rawFile && previewImage) {
      payload.append('imageBase64', previewImage);
    } else {
      payload.append('image', user.image);
    }

  
    try {
      const res = await fetch(config.apiEndpoint, {
        method: 'POST',
        body: payload.toString(),
        headers: {'Content-Type': 'application/x-www-form-urlencoded' },
      });
      const data = await res.json();

      if (data.success) 
      {
        const updated = {
          ...user,
          name: formData.name,
          mobile: formData.mobile,
          image: data.url
        };
        setUser(updated);
        localStorage.setItem('user', JSON.stringify(updated));
        toast.success('Profile saved!');
        setEditMode(false);
        setRawFile(null);
      }

      else 
      {
       console.log('Failed');
      }


    } 
    catch (err) 
    {
      console.error(err);
      toast.error('Error saving profile: ' + err.message);
    } 
    finally
    {
      setIsLoading(false);
    }
  };

  if (!user) return <p>Loading user data...</p>;
  if (isLoading) return <LoadingScreen message="Saving..." />;

  return (
    <Card
      className="p-4 border rounded-3 shadow-sm"
      style={{ maxWidth: 720, margin: '1rem auto', backgroundColor: '#fff' }}
    >
      <Row className="g-4 align-items-center">
        <Col xs={12} md={4} className="text-center">
          <Image
            src={editMode ? previewImage : user.image || config.defaultProfileImage}
            roundedCircle
            alt="User Profile"
            style={{
              width: 160,
              height: 160,
              objectFit: 'cover',
              border: '3px solid #dee2e6',
              boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
              transition: 'transform 0.3s ease',
              cursor: editMode ? 'pointer' : 'default',
            }}
          />
          {editMode && (
            <Form.Group controlId="formFile" className="mt-2">
              <Form.Control type="file" accept="image/*" onChange={handleImageChange} />
            </Form.Group>
          )}
          <h4 className="mt-3 mb-1 fw-semibold text-dark">
            {editMode ? (
              <Form.Control
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="text-center"
              />
            ) : (
              user.name
            )}
          </h4>
          <small className="text-muted fst-italic">{user.registrationDate}</small>
        </Col>

        <Col xs={12} md={8}>
          <div className="px-md-3">
            <div className="mb-4">
              <h6 className="text-secondary mb-1">Email Address</h6>
              <p className="fs-6 text-dark">{user.email}</p>
            </div>

            <div className="mb-5">
              <h6 className="text-secondary mb-1">Phone Number</h6>
              {editMode ? (
                <Form.Control
                  name="mobile"
                  value={formData.mobile}
                  onChange={handleChange}
                />
              ) : (
                <p className="fs-6 text-dark">{user.mobile || '8093512506'}</p>
              )}
            </div>

            <div className="d-flex gap-3 flex-wrap justify-content-md-end">
              {editMode ? (
                <>
                  <Button variant="success" className="rounded-pill px-4 shadow-sm" onClick={handleSave}>
                    Save
                  </Button>
                  <Button
                    variant="secondary"
                    className="rounded-pill px-4 shadow-sm"
                    onClick={() => {
                      setEditMode(false);
                      setPreviewImage(user.image || config.defaultProfileImage);
                      setRawFile(null);
                    }}
                  >
                    Cancel
                  </Button>
                </>
              ) : (
                <Button variant="primary" className="rounded-pill px-4 shadow-sm" onClick={() => setEditMode(true)}>
                  Edit Profile
                </Button>
              )}
              <Button variant="outline-danger" className="rounded-pill px-4 shadow-sm" onClick={handleLogout}>
                Logout
              </Button>
            </div>
          </div>
        </Col>
      </Row>
    </Card>
  );
}
