import React from 'react';
import Cart from './Cart';
import { useNavigate } from 'react-router-dom';  // <-- import useNavigate
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faCartPlus,faCreditCard  } from '@fortawesome/free-solid-svg-icons';

const CartContainer = ({ cartItems, addToCart, removeFromCart, deleteFromCart }) => {
  const navigate = useNavigate();  // <-- call useNavigate inside the component

  if (cartItems.length === 0) return <p>Your cart is empty.</p>;

  return (
    <div className="container mt-5 bg-light p-4 rounded shadow">
      <h2>Your Cart</h2>
      {cartItems.map(item => (
        <Cart
          key={item.id}
          image={item.image}
          title={item.title}
          price={item.price}
          quantity={item.quantity}
          style={item.style}
          size={item.size}
          length={item.length}
          addQuantity={() => addToCart(item)}
          removeQuantity={() => removeFromCart(item)}
          onDelete={() => deleteFromCart(item)}
        />
      ))}

      <div className='mt-4 d-flex justify-content-between align-items-center mt-4 gap-2 sm-4'> 

        <button
          className="btn btn-primary mt-2 w-50"
          onClick={() => navigate("/home")}
          title='Buy More'
        >
          <FontAwesomeIcon icon={faCartPlus} className="me-2" /> Buy More
        </button>

        <button
          className="btn btn-success mt-2 w-50"
          onClick={() => navigate("/checkout")}
          title='Proceed to checkout'
        >
         <FontAwesomeIcon icon={faCreditCard } className="me-2" /> Proceed to Checkout
        </button>
      </div>
    </div>
  );
};

export default CartContainer;
