
import { useState, useEffect ,useContext} from 'react';
import ProductCard from '../product/card/ProductCard';
import LoadingScreen from '../loadingScreen/LoadingScreen';
import { toast } from 'react-toastify';
import ConfigContext from '../../script/ConfigContext';

function Home() {

    const config = useContext(ConfigContext);
    // State to store the products
    // and loading state
    const [products, setProducts] = useState(() => {
    try {
        const saved = localStorage.getItem('products');
        if (!saved || saved === 'undefined') return [];
        const parsed = JSON.parse(saved);
        return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
        console.error('Error parsing products from localStorage:', error);
        return [];
    }
    });

    const [isLoading, setLoading] = useState(true);

    // Fetch products from the API
    // and store them in local storage to be displayed while fetching new data
    useEffect(() => {
        setLoading(true);
        const fetchProducts = async () => {
            try {
                const params = new URLSearchParams({ Action: 'product' });

                const apiEndpoint = `${config.apiEndpoint}?${params.toString()}`;
                const response = await fetch(apiEndpoint, {
                    method: 'GET',
                });

                // Handle the response
                if (!response.ok) {
                    throw new Error(`Error: ${response.statusText}`);
                }

                const product = await response.json();

                if(product.data === undefined || product.data === null) {
                    toast.error('No products available,  from Server.');
                    toast.success('Loading products from local storage.');
                    setProducts(config.products);
                    localStorage.setItem('products', JSON.stringify(config.products));
                }
                else
                {
                    setProducts(product.data);
                    localStorage.setItem('products', JSON.stringify(product.data));
                }
                
            } 
            catch (error) {
                console.error('Error fetching products:', error);
                toast.error('Failed to fetch products. Displaying saved data.');
                setProducts(config.products);
            } 
            finally {
                setLoading(false);
            }
        };

        fetchProducts();
    }, [config.apiEndpoint, config.products]);

    // This prevents scrolling when the loading screen is displayed
    useEffect(() => {
        document.body.style.overflow = isLoading ? 'hidden' : 'auto';
    }, [isLoading]);

  return (
    // LOADING SCREEN / WELCOME MESSAGE / PRODUCT CARDS
    <div className="container">
         {isLoading && products.length == 0 && <LoadingScreen message="Loading products..." />} {/* LOADING SCREEN*/}
       <div className="row g-0">


        { Array.isArray(products) && products.length > 0 ? (
            products.map(product => (
                <div className="col-12 col-sm-6 col-md-4 col-lg-3" key={product.id}>
                <ProductCard
                    id={product.id}
                    imageSrc={product.imageSrc || config.fallbackImage}
                    title={product.title}
                    price={product.price}
                    soldOut={product.soldOut}
                    discountPercent="10"
                />
                </div>
            ))
            ) : (
            <div className="col-12 text-center py-4">
                <p>No products available.</p>
            </div>
            )
        }




       </div>

    </div>
  );
}
export default Home;