import './ProductCard.css'; // Custom styles for the card
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart, faBell ,faCheckCircle   } from '@fortawesome/free-solid-svg-icons';
import image from '../../images/default.jpg';
import config from '../../../script/config'; // Importing configuration for rupee symbol
import { toast } from 'react-toastify';
import { useOutletContext } from 'react-router-dom';
import { useState } from 'react';

const ProductCard = ({ id, imageSrc, title, price, soldOut, discountPercent }) => {
  const { addToCart } = useOutletContext();
   const [notified, setNotified] = useState(false);

  // Function to extract the numeric value from the price string
  const extractNumber = (str) => {
    const withoutRs = str.replace(/Rs\.?\s*/i, '');
    const cleanedString = withoutRs.replace(/[^0-9.]/g, '');
    const amount = parseFloat(cleanedString);
    return isNaN(amount) ? null : amount;
  };

    const handleNotify = () => {
    if (!notified) {
      setNotified(true);
      toast.info('You will be notified');
    }
  };

  const priceNum = extractNumber(price.toString());
  const discountNum = Number(discountPercent) || 0;
  const validDiscount = isNaN(discountNum) ? 0 : discountNum;
  const discountPrice = priceNum - (priceNum * validDiscount) / 100;

  const productUrl = `#/products/${id}`;

  return (
    <a
      href={productUrl}
      target="_blank"
      rel="noopener noreferrer"
      className="card-wrapper-link"
      onClick={(e) => {
        // Prevent navigating when clicking inside the Add to Cart button
        if (soldOut || e.target.closest('button')) {
          e.preventDefault();
        }
      }}
    >
      <div className={`card-wrapper product-card-wrapper underline-links-hover`}>
        <div className="card card--media color-background-1 gradient">
          <div className="card__inner ratio">
            <div className="card__media">
              <div className={` media media--transparent media--hover-effect ${soldOut ? 'card--soldout' : ''}`}>
                {discountPercent > 0 && (
                  <div className="card__badge">
                    <span className="badge badge--discount">{discountPercent}% OFF</span>
                  </div>
                )}
                <img
                  src={imageSrc}
                  alt={title}
                  className="motion-reduce"
                  onError={(e) => {
                    e.target.onerror = null;
                    e.target.src = image;
                  }}
                />
              </div>
            </div>
            <div className="card__content">
              {soldOut && (
                <div className={`card__badge bottom left ${soldOut ? 'card--soldout' : ''}`}>
                  <span className="badge badge--bottom-left color-inverse">Sold out</span>
                </div>
              )}
            </div>
          </div>

          <div className={`card__content d-flex flex-column`}>
            <div className="card__information">
              <h3 className={`card__heading h5    ${soldOut ? 'card--soldout' : ''}   `}>
                {title}
              </h3>

              <div className={`price ${soldOut ? 'card--soldout' : ''}`}>
                <div className="price__container">
                  {discountPercent > 0 ? (
                    <>
                      <span className="price--original"> {config.rupeeSymbol} {priceNum.toLocaleString('en-IN')}</span>
                      <span className="price--discount">
                        {config.rupeeSymbol} {discountPrice.toLocaleString('en-IN')} ({validDiscount}% OFF)
                      </span>
                    </>
                  ) : (
                    <span className={`price-item price-item--regular ${soldOut ? 'card--soldout' : ''}`}>
                      {config.rupeeSymbol} {discountPrice.toLocaleString('en-IN')}
                    </span>
                  )}
                </div>
              </div>
            </div>

            {soldOut && (
              <>
                <div className={`card__badge bottom left ${soldOut ? 'card--soldout' : ''}`}>
                  <span className="badge badge--bottom-left color-inverse">Sold out</span>
                </div>

                <button
                className={`btn btn-secondary ${notified ? 'disabled': ''} `}
                onClick={(e) => {
                  e.preventDefault(); // Prevent <a> navigation when clicking button
                  handleNotify();
                }}
              >
                <FontAwesomeIcon icon={notified ? faCheckCircle : faBell} className="me-2" />
                Notify Me
              </button>
              </>
            )}

            {/* Add to Cart Button */}
            {!soldOut && (
              <button
                className="btn btn-primary"
                onClick={(e) => {
                  e.preventDefault(); // Prevent <a> navigation when clicking button
                  addToCart({ id, title, price: priceNum, quantity: 1, image: imageSrc });
                  toast.success(`${title}: added to cart!`);
                }}
              >
                <FontAwesomeIcon icon={faShoppingCart} /> Add to Cart
              </button>
            )}
          </div>
        </div>
      </div>
    </a>
  );
};

export default ProductCard;
