import React,{ useState, useEffect , useContext} from 'react';
import { Button, Row, Col, Container, Image } from "react-bootstrap";
import './ProductDescription.css';
import LoadingScreen from '../../loadingScreen/LoadingScreen';
import { useParams,useOutletContext } from 'react-router-dom';
import { toast } from 'react-toastify';
import ConfigContext from '../../../script/ConfigContext'; 


const ProductDescription = ({productOptions,setProductOptions}) => {

  const config = useContext(ConfigContext);

  const { addToCart } = useOutletContext();
  const [quantity, setQuantity] = useState(1);
  const [product, setProduct] = useState();
  const [isLoading, setLoading] = useState(false);
  const { id } = useParams();
  const idStr = id?.toString();

 const productData = React.useMemo(() => config.productDescription[idStr], [config.productDescription, idStr]);

 // Function to extract the numeric value from the price string
  // This function removes the "Rs." prefix and any non-numeric characters
const extractNumber = (str = '') => {
    if (typeof str !== 'string') return 0;
    const withoutRs = str.replace(/Rs\.?\s*/i, '');
    const cleanedString = withoutRs.replace(/[^0-9.]/g, '');
    const amount = parseFloat(cleanedString);
    return isNaN(amount) ? 0 : amount;
};

  // Extract the numeric value from the price string
  // and convert it to a number
  const priceNum = product?.price ? extractNumber(product.price) : 0;
  

  const increment = () => setQuantity(q => q + 1);
  const decrement = () => setQuantity(q => (q > 1 ? q - 1 : 1));

const handleOptionChange = (key, value) => {
  setProductOptions(prev => ({
    ...prev,
    [key]: value
  }));
};

  // Fetch product details from the API
  useEffect(() => {
      if(!id) {return;}
        setQuantity(1);
        setLoading(true);
        const fetchDescription = async () => {
          try {
            const params = new URLSearchParams({ Action: 'productdescription' ,ID:Number(id)});
            
            const apiEndpoint = `${config.apiEndpoint}?${params.toString()}`;
            console.log('endPoint', apiEndpoint);

              const response = await fetch(apiEndpoint, {
                  method: 'GET',
              });

              // Handle the response
              if (!response.ok) {
                  throw new Error(`Error: ${response.statusText}`);
              }

            const result = await response.json();

            if (result.data === undefined || result.data === null) 
            {
              if (productData) 
              {
                toast.error('No product available from Server. Showing local data.');
                setProduct(productData);
              } 
              else 
              {
                toast.error('No product data found.');
              }
            } 
            else 
            {
              setProduct(result.data);
              toast.success('Product details fetched successfully!');
            }
          } 
          catch (error) {
              console.error('Error fetching products:', error);
              toast.error('Error fetching product details. Please try again later.');
          } 
          finally 
          {
              setLoading(false);
          }
      };
         fetchDescription();
     }, [id, productData, config.apiEndpoint]);

     

  if (isLoading) {
    return <LoadingScreen message="Loading product..." />;
  }

  if (!product?.title) {
    return <div className="text-center my-5 text-muted">No product found.</div>;
  }

  return (
    // LOADING SCREEN / WELCOME MESSAGE / PRODUCT CARDS
    <Container className="my-5 position-relative">
    { 
     isLoading && (
          <div
            style={{
              position: 'absolute',
              top: 0, left: 0, right: 0, bottom: 0,
              backgroundColor: 'rgba(85, 82, 82, 0.15)',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              zIndex: 10,
            }}
          >
      <LoadingScreen message="Loading products..." />
    </div>
    
  )}

      <Row className="gy-4">
        {/* Images */}
        <Col md={6}>
          <div className="main-image-wrapper mb-3">
            <Image src={product.imageSrc?.[0] || config.fallbackImage} fluid rounded className="main-image" />
          </div>
          <Row className="g-2">
            <Col xs={6}>
              <Image src={product.imageSrc?.[1] || config.fallbackImage} fluid rounded className="sub-image" />
            </Col>
            <Col xs={6}>
              <Image src={product.imageSrc?.[2] || config.fallbackImage} fluid rounded className="sub-image" />
            </Col>
          </Row>
        </Col>

        {/* Details */}
        <Col md={6}>
          <h1>{product.title}</h1>

          <div className="mb-3">
            <strong>Style</strong>
            <div className="d-flex flex-wrap gap-2 mt-2">
              {product.style.map(style => (
              <Button
                  key={style}
                  variant={productOptions.style === style ? "dark" : "outline-secondary"}
                  size="sm"
                  className="me-2 mb-2"
                  onClick={() => handleOptionChange('style',style)}
                >
                  {style}
                </Button>
              ))}
            </div>
          </div>

          <div className="mb-3">
            <strong>Length</strong>
            <div className="d-flex flex-wrap gap-2 mt-2">
              {product.length.map(length => (
                <Button 
                  key={length}
                  variant={productOptions.length === length ? "dark" : "outline-secondary"}
                  size="sm"
                  onClick={()=> handleOptionChange('length', length)}
                >
                  {length}
                </Button>
              ))}
            </div>
          </div>

          <div className="mb-3">
            <strong>Size</strong>
            <div className="d-flex flex-wrap gap-2 mt-2">
              { product.size.map(size => (
                <Button 
                variant={productOptions.size === size ? "dark" : "outline-secondary"}
                size="sm" 
                key={size}
                onClick={()=> handleOptionChange('size',size)}
                >{size}</Button>
              ))}
            </div>
          </div>

          <h4 className="text-muted d-flex align-items-center gap-2">
            {config.rupeeSymbol}{priceNum.toLocaleString('en-IN')}
            <small className={product.soldOut ? "text-danger" : "text-success"}>
              {product.soldOut ? "Sold out" : "In stock"}
            </small>
          </h4>

         <div className="d-flex align-items-center gap-3 mb-3">
          <Button variant="outline-secondary" size="sm" onClick={decrement}>-</Button>
          <span>{quantity}</span>
          <Button variant="outline-secondary" size="sm" onClick={increment}>+</Button>
      </div>
          {
          product.soldOut ? (
            <Button variant="secondary" disabled className="w-100">
              Sold out
            </Button>
          ) : (
            <Button
            variant="primary"
              className="w-100"
              onClick={() => {
                addToCart({
                  id: product.id || id,
                  title: product.title,
                  price: priceNum,
                  quantity: quantity,
                  image: product.imageSrc?.[0] || config.fallbackImage,
                  style: productOptions.style,
                  size: productOptions.size,
                  length: productOptions.length,
                });

                toast.success(`${product.title} added to cart!`);
                setQuantity(1);
              }}
            >
              Add to cart
          </Button>
          )
        }
          <hr />

          <div>
            <h5>{product.title}:</h5>
            <ul>
              {
                product.description.map((description) => 
                (
                  <li key={description}>{description}</li>
                ))
              }
            </ul>
          </div>
        </Col>
      </Row>
    </Container>

);
};

export default ProductDescription;
