import React from 'react';
import config from '../../script/config';

const Cart = ({ image, title, price, quantity, style, size, length, addQuantity, removeQuantity, onDelete }) => {
  
  return (
    <div className="d-flex align-items-center mb-3 p-3 border rounded shadow-sm">
      {/* Product Image */}
      <img
        src={image}
        alt={title}
        className="img-thumbnail"
        style={{ width: '100px', height: '100px', objectFit: 'cover' }}
      />

      {/* Product Details */}
      <div className="ms-4 flex-grow-1">
          <h5 className="mb-1">{title}</h5>
          <div>Price : <span className="fw-semibold text-success">{config.rupeeSymbol} {(price * quantity).toLocaleString('en-IN')}</span>
          </div>
          <div>Style : <span className="fw-semibold text-success">{style || '-'}</span></div>
          <div>Length : <span className="fw-semibold text-success">{length || '-'}</span></div>
          <div>Size : <span className="fw-semibold text-success">{size || '-'}</span></div>


          {/* Quantity Controls */}
          <div className="d-flex align-items-center mt-2">
            <button
              className="btn btn-outline-secondary btn-sm me-2"
              onClick={removeQuantity}
              title="Decrease quantity"
            >
              −
            </button>
            <span className="fw-bold">{quantity}</span>
            <button
              className="btn btn-outline-secondary btn-sm ms-2"
              onClick={addQuantity}
              title="Increase quantity"
            >
              +
            </button>
          </div>
      </div>

      {/* Delete Button */}
      <button 
          className="btn btn-outline-danger btn-sm"
          onClick={onDelete}
          title="Remove item from cart">
          ❌
      </button>
    </div>
  );
};

export default Cart;
