import React, { useState } from 'react';

import { useNavigate } from 'react-router-dom';

export default function Contact({ contact, onChange, onNext }) {
  const [error, setError] = useState('');
  const navigate = useNavigate();

  // Simple email regex for validation
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const handleNext = () => {
    if (!emailPattern.test(contact.email)) {
       setError('Please enter a valid email address.');
      return;
    }
    setError('');
    onNext(); 
  };

  const backToCart = () => {
    navigate('/cart');
  }

  return (
    <div className="card p-4 shadow-sm">
      <h4 className="mb-3">Contact Information</h4>
      <div className="mb-3">
        <label className="form-label" htmlFor="email">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          className="form-control"
          value={contact.email}
          onChange={onChange}
          required
        />
        {error && <div className="text-danger mt-1">{error}</div>}
      </div>
      <div className='d-flex justify-content-between'>
        <button className="btn btn-secondary" onClick={backToCart}>&larr; Back to cart</button>
        <button className="btn btn-primary" onClick={handleNext}>Continue to Shipping &rarr;</button>
      </div>
    </div>
  );
}