import { toast } from 'react-toastify';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

const generatePDFBlob = () => {
  const input = document.getElementById('invoice');
  if (!input) return Promise.reject(new Error('Invoice element not found'));

  return html2canvas(input, {
    useCORS: true,
    allowTaint: false,
    scale: 2,
    backgroundColor: null,
    printBackground: true,
  }).then((canvas) => {
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    return pdf.output('blob');
  });
};

export const blobToBase64 = (blob) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });

export const downloadPDF = (invoiceNumber) => {
  generatePDFBlob()
    .then((pdfBlob) => {
      const url = URL.createObjectURL(pdfBlob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `invoice_${invoiceNumber}_${Date.now()}.pdf`;
      link.click();
      URL.revokeObjectURL(url);
      toast.info('PDF downloaded successfully');
    })
    .catch((error) => {
      console.error(error);
      toast.error('Failed to generate PDF for download');
    });
};

export const sendMail = async (invoiceNumber, config, setSending, recipient) => {

  setSending(true);

   setTimeout(() => {
     setSending(false);
     toast.info(`Email will be sent shortly to ${recipient}`);
    }, 3000);

  try {
    const pdfBlob = await generatePDFBlob();
    const base64PDF = await blobToBase64(pdfBlob);
    
    const formData = new URLSearchParams();
    formData.append('Action', 'email');
    formData.append('Type', 'invoice');
    formData.append('InvoiceNumber', invoiceNumber);
    formData.append('PdfBase64', base64PDF);
    formData.append('Receiver', recipient);
    formData.append('Subject', `Invoice #${invoiceNumber}`);
    formData.append('Body', 
   `
 <div style="max-width: 600px; margin: 40px auto; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; font-size: 16px; color: #444444; background-color: #fafafa; padding: 30px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.1);">
  <div style="background: #ffffff; padding: 30px; border-radius: 10px; border: 1px solid #e0e0e0;">
    
    <h1 style="font-weight: 700; color: #2a3f54; margin-bottom: 20px; font-size: 28px; letter-spacing: 1px;">
      Thank You for Your Purchase!
    </h1>

    <p style="font-size: 16px; line-height: 1.6; margin-bottom: 20px;">
      Dear Customer,
    </p>

    <p style="font-size: 16px; line-height: 1.6; margin-bottom: 20px;">
      We sincerely appreciate your business and hope you enjoy your order.
    </p>

    <p style="font-size: 16px; line-height: 1.6; margin-bottom: 30px; font-weight: 600; color: #1a73e8;">
      Attached is your invoice for reference. If you have any questions or concerns, please don't hesitate to contact us.
    </p>

    <div style="background-color: #e8f0fe; border-left: 6px solid #1a73e8; padding: 20px 25px; border-radius: 6px; margin-bottom: 40px;">
      <p style="margin: 0; font-size: 16px; font-weight: 600; color: #1a73e8;">
        Invoice Number: <span style="font-weight: 400; color: #333;">${invoiceNumber}</span>
      </p>
      <p style="margin: 5px 0 0 0; font-size: 16px; font-weight: 600; color: #1a73e8;">
        Date: <span style="font-weight: 400; color: #333;">${new Date().toLocaleDateString()}</span>
      </p>
    </div>

    <p style="font-size: 16px; line-height: 1.6; margin-bottom: 10px;">
      Warm regards,<br>
      <strong style="color: #2a3f54;">MR SINGH MART</strong>
    </p>
    
    <hr style="border: none; border-top: 1px solid #ddd; margin: 40px 0;" />
    
    <p style="font-size: 12px; color: #999999; text-align: center; margin: 0;">
      This is an automated email. Please do not reply directly to this message.
    </p>

  </div>
</div>

`
);

    
    const response = await fetch(config.apiEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: formData.toString(),
    });

    const responseText = await response.text();
    const responseData = JSON.parse(responseText);


    if (!response.ok) {
       toast.error(`HTTP error! status: ${response.status} - ${responseText}`);
    }

    if(!responseData.success )
    {
       toast.error(`ERROR : ${responseData.message}`);
    }
    else
    {
      toast.success(responseData.message);
    }

    
  } 
  catch (error) 
  {
    console.error(error);
    toast.error('Failed to send invoice');
  } 
  finally 
  {
    setSending(false);
  }
};
