import React, { useState } from 'react';
import QRCode from "../invoice/QRCodeComponent";
import config from '../../script/config';

export default function Payment({totalAmount, payment, onChange, onBack, onSubmit }) {
const [paymentMode, setPaymentMode] = useState('card'); 

  const formatCardNumber = (value) => {
    const digits = value.replace(/\D/g, '');
    return digits.match(/.{1,4}/g)?.join('-') || '';
  };

  const handleCardNumberChange = (e) => {
    const rawValue = e.target.value;
    const formattedValue = formatCardNumber(rawValue);
    onChange({
      target: {
        name: 'cardNumber',
        value: formattedValue
      }
    });
  };

  return (
    <form onSubmit={onSubmit} className="card p-4 shadow-sm">
      <h4 className="mb-3">Select Payment Method</h4>

      {/* Toggle Buttons */}
      <div className="btn-group mb-4 w-100" role="group">
        <button
          type="button"
          className={`btn btn-outline-primary ${paymentMode === 'card' ? 'active' : ''}`}
          onClick={() => setPaymentMode('card')}
        >
          Card
        </button>
  
        <button
          type="button"
          className={`btn btn-outline-primary ${paymentMode === 'upi' ? 'active' : ''}`}
          onClick={() => setPaymentMode('upi')}
        >
          UPI
        </button>
      </div>

      {(paymentMode === 'card') && (
        <>
          <div className="mb-3">
            <label className="form-label" htmlFor="cardNumber">Card Number</label>
            <input
              id="cardNumber"
              name="cardNumber"
              className="form-control"
              value={payment.cardNumber}
              onChange={handleCardNumberChange}
              placeholder="1234-5678-9012-3456"
              maxLength={19}
              required
            />
          </div>

          <div className="row mb-3">
            <div className="col-md-6">
              <label className="form-label" htmlFor="expiry">Expiry Date (MM/YY)</label>
              <input
                id="expiry"
                name="expiry"
                className="form-control"
                value={payment.expiry}
                onChange={onChange}
                placeholder="MM/YY"
                required
              />
            </div>
            <div className="col-md-6">
              <label className="form-label" htmlFor="cvv">CVV</label>
              <input
                id="cvv"
                name="cvv"
                className="form-control"
                value={payment.cvv}
                onChange={onChange}
                maxLength={3}
                type="password"
                required
              />
            </div>
          </div>

          <div className="mb-3">
            <label className="form-label" htmlFor="nameOnCard">Name on Card</label>
            <input
              id="nameOnCard"
              name="nameOnCard"
              className="form-control"
              placeholder="MR SINGH"
              value={payment.nameOnCard}
              onChange={onChange}
              required
            />
          </div>
        </>
      )}

      {/* UPI Fields */}
      {paymentMode === 'upi' && (
        <div className="mb-3">
         
           <QRCode id={config.upiID} money={totalAmount} size={210} />
        </div>
      )}

      {/* Action Buttons */}
      <div className="d-flex justify-content-between mt-4">
        <button type="button" className="btn btn-secondary" onClick={onBack}>&larr; Back</button>
        <button type="submit" className="btn btn-success">Pay Now &rarr;</button>
      </div>
    </form>
  );
}
