import { useState } from 'react';
import Profile from './Profile';
import SavedAddresses from './SavedAddresses';
import MyOrders from './MyOrders';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {faMapMarkerAlt, faBoxOpen, faUserCircle } from '@fortawesome/free-solid-svg-icons';
import { useNavigate } from 'react-router-dom';


export default function UserDashboard({user, setIsLoggedIn, savedAddresses,setSavedAddresses, allOrders}) {
  const [activeTab, setActiveTab] = useState('profile');
  const  navigate = useNavigate();

  const handleClose = ()=>{
    setTimeout(()=> {
      navigate("/home")
    }, 300)
  }
/** RENDER PAGE
* This is to display the content of page based on  tab selected
*/
  const renderContent = () => {
    switch (activeTab) {
      case 'profile':
        return <Profile 
            user={user} 
            setIsLoggedIn={setIsLoggedIn}
          />;
      case 'addresses':
        return <SavedAddresses 
              savedAddresses={savedAddresses}
              setSavedAddresses={setSavedAddresses}
          />;
      case 'orders':
        return <MyOrders 
            allOrders ={allOrders}
        />;
    }
  };

  return (
    <div className="card p-4 shadow-sm">
      <h4 className="mb-3">My Account</h4>

      {/* Menu Buttons */}
      <div className="btn-group mb-4 w-100" role="group">
        <button
          type="button"
          className={`btn btn-outline-primary ${activeTab === 'profile' ? 'active' : ''}`}
          onClick={() => setActiveTab('profile')}
        >
        <FontAwesomeIcon icon={faUserCircle} className="me-2" />
          Profile
        </button>

        <button
          type="button"
          className={`btn btn-outline-primary ${activeTab === 'addresses' ? 'active' : ''}`}
          onClick={() => setActiveTab('addresses')}
        >
       <FontAwesomeIcon icon={faMapMarkerAlt} className="me-2" />
          Saved Addresses
        </button>

        <button
          type="button"
          className={`btn btn-outline-primary ${activeTab === 'orders' ? 'active' : ''}`}
          onClick={() => setActiveTab('orders')}
        >
       <FontAwesomeIcon icon={faBoxOpen} className="me-2" />
          My Orders
        </button>
      </div>

      {/* Dynamic Content Area */}
      <div className="border-top pt-3">
        {renderContent()}
      </div>

     <button
        className="btn btn-secondary"
        onClick={handleClose}
        >
          Close
            </button>
    </div>
  );
}
