import {  getCookie } from './cookies';


export async function logout(setIsLoggedIn, apiEndpoint, toast, navigate, setIsLoading) 
{
  setIsLoading(true);
  const token = getCookie('shop-token');
  try {
    const formData = new URLSearchParams();
    formData.append('Action', 'logout');
    formData.append('Token', token);

    const response = await fetch(apiEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: formData.toString(),
    });

    console.log('formData.toString()', formData.toString());

    if (!response.ok) {
      toast.error('Logout failed. Please try again.');
      return;
    }

    const result = await response.json();
    console.log('response json', result);

    if (result.success) {
      setIsLoading(false);
      
      setIsLoggedIn(false);

      localStorage.removeItem('token');
      localStorage.removeItem('user');

      toast.success('Logout successful!');
      navigate('/home');
    } else {
      setIsLoading(false);
      toast.error(result.message || 'Logout failed. Please try again.');
    }
  } catch (error) {
     setIsLoading(false);
    console.error('Logout failed:', error);
    toast.error('Something went wrong. Please try again.');
  }
}
