export async function UserHistory(apiEndpoint, email, setSavedAddresses, setAllOrders) {
console.log('Fetching user history for email:', email);
  if (!email) {
    console.error('Email is required to fetch user history');
    return;
  }
  const formData = new URLSearchParams();
  formData.append('Action', 'history');
  formData.append('Email', email);

  try {
    const response = await fetch(apiEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formData.toString(),
    });

    const data = await response.json();

    console.log('Response from UserHistory:', data);
    if (data.success) 
    {
        setSavedAddresses(data.data.addresses || []);
        setAllOrders(data.data.orders || []);
        console.log('User history fetched successfully:', data.data);
    }
  } 
  catch (error) 
  {
   console.log(error);
    setSavedAddresses([]);
    setAllOrders([]);
  }
}
