import React, { useEffect, useState, useCallback, useMemo } from 'react';
import Contact from './Contact';
import Shipping from './Shipping';
import Method from './Method';
import Payment from './Payment';
import OrderSummary from './OrderSummary';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import config from '../../script/config';
import { validateCoupon } from '../../script/discountUtils';
import Banner from '../promoBanner/Banner';

const steps = ['Contact', 'Shipping', 'Method', 'Payment'];

export default function Checkout({
  cartItems,
  promoCodeDiscount,
  setPromoCodeDiscount,
  gstAmount,
  setGstAmount,
  shippingCharge,
  setShippingCharge,
  setCustomerInformation
}) {
  const navigate = useNavigate();

  // Group form data state into objects
  const [contact, setContact] = useState({ email: '' });
  const [shippingAddress, setShippingAddress] = useState({
    firstName: '',
    lastName: '',
    address: '',
    apartment: '',
    city: '',
    country: 'India',
    state: 'Karnataka',
    zip: '',
    phone: ''
  });
  const [shippingMethod, setShippingMethod] = useState('');
  const [payment, setPayment] = useState({
    cardNumber: '',
    expiry: '',
    cvv: '',
    nameOnCard: ''
  });

  const [discountCode, setDiscountCode] = useState('');
  const [appliedCoupon, setAppliedCoupon] = useState('');
  const [step, setStep] = useState(1);

  // Calculate subtotal using useMemo to avoid recalculations unless cartItems change
  const subtotal = useMemo(() => {
    return cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
  }, [cartItems]);

  // Calculate GST and total amount, memoized
  const calculatedGst = useMemo(() => (subtotal * config.gstRate) / 100, [subtotal]);
  const totalAmount = useMemo(() => subtotal + calculatedGst + shippingCharge - promoCodeDiscount, [
    subtotal,
    calculatedGst,
    shippingCharge,
    promoCodeDiscount
  ]);

  // Update GST amount state on changes
  useEffect(() => {
    setGstAmount(calculatedGst);
  }, [calculatedGst, setGstAmount]);

  // Step navigation handlers
  const nextStep = useCallback(() => setStep((prev) => Math.min(prev + 1, steps.length)), []);
  const prevStep = useCallback(() => setStep((prev) => Math.max(prev - 1, 1)), []);

  // Generic handler creator for updating state and syncing with customer info
  const createChangeHandler = (stateSetter, stateObj, syncCustomer = false) => (e) => {
    const updated = { ...stateObj, [e.target.name]: e.target.value };
    stateSetter(updated);
    if (syncCustomer) {
      setCustomerInformation((prev) => ({ ...prev, ...updated }));
    }
  };

  // Handlers
  const handleContactChange = createChangeHandler(setContact, contact, true);
  const handleShippingAddressChange = createChangeHandler(setShippingAddress, shippingAddress, true);
  const handleShippingMethodChange = (e) => setShippingMethod(e.target.value);
  const handlePaymentChange = (e) => setPayment((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  const handleDiscountCodeChange = (e) => setDiscountCode(e.target.value);

  // Coupon application logic
  const applyDiscount = () => {
    const { valid, amount, code } = validateCoupon(discountCode, config.coupons);

    if (!valid) {
      setPromoCodeDiscount(0);
      setAppliedCoupon('');
      toast.error('Invalid discount code. Please try again.');
      return;
    }

    setPromoCodeDiscount(amount);
    setAppliedCoupon(code);
    toast.success(`Discount applied! You saved ${config.rupeeSymbol}${amount}.`);
  };

  const removeCoupon = () => {
    setPromoCodeDiscount(0);
    setAppliedCoupon('');
    setDiscountCode('');
    toast.info('Coupon removed. You can apply another coupon now.');
  };

  // Payment submit handler
  const handleSubmit = (e) => {
    e.preventDefault();
    toast.info('Payment Successfully');
    setTimeout(() => navigate('/invoice'), 500);
  };

  // Render current step component
  const renderStepContent = () => {
    switch (step) {
      case 1:
        return <Contact contact={contact} onChange={handleContactChange} onNext={nextStep} showBack={false} />;
      case 2:
        return <Shipping shippingAddress={shippingAddress} onChange={handleShippingAddressChange} onNext={nextStep} onBack={prevStep} />;
      case 3:
        return <Method shippingMethod={shippingMethod} onChange={handleShippingMethodChange} onNext={nextStep} onBack={prevStep} />;
      case 4:
        return <Payment payment={payment} onChange={handlePaymentChange} onBack={prevStep} onSubmit={handleSubmit} totalAmount={totalAmount} />;
      default:
        return null;
    }
  };

  // Render step indicators cleanly
  const renderStepIndicators = () => (
    <div className="mb-4 d-flex justify-content-between">
      {steps.map((label, index) => {
        const stepNum = index + 1;
        const active = stepNum === step;
        const completed = stepNum < step;

        let circleBgClass;
        if (completed) {
          circleBgClass = 'bg-success';
        } else if (active) {
          circleBgClass = 'bg-primary';
        } else {
          circleBgClass = 'bg-light text-muted';
        }
        const circleTextColor = completed || active ? 'white' : '#6c757d';
        let labelTextClass;
        if (active) {
          labelTextClass = 'text-primary';
        } else if (completed) {
          labelTextClass = 'text-success';
        } else {
          labelTextClass = 'text-muted';
        }

        return (
          <React.Fragment key={label}>
            {index > 0 && <div className="step-line flex-grow-1 mx-2" />}
            <div className="text-center" style={{ width: '60px' }}>
              <div
                className={`rounded-circle mx-auto mb-1 ${circleBgClass}`}
                style={{
                  width: '30px',
                  height: '30px',
                  lineHeight: '30px',
                  color: circleTextColor,
                  fontWeight: 'bold'
                }}
              >
                {stepNum}
              </div>
              <small className={labelTextClass}>{label}</small>
            </div>
          </React.Fragment>
        );
      })}
      <style jsx>{`
        .step-line {
          border-top: 3px dotted;
          color: rgb(0, 0, 0);
          margin-top: 1.5%;
        }
      `}</style>
    </div>
  );

  // Show empty cart message if cart is empty
  if (cartItems.length === 0) {
    return (
      <div className="container text-center py-5">
        <h2>Your cart is empty</h2>
        <a href="#/home" className="btn btn-primary mt-3">
          Back to Shopping
        </a>
      </div>
    );
  }

  return (
    <div className="container py-4">
      <Banner promoCode={config.promoCode} discountAmount={config.promoCodeDiscount} rupeeSymbol={config.rupeeSymbol} />
      <h1 className="mb-4 text-center transparent">Checkout</h1>

      {renderStepIndicators()}

      <div className="row">
        <div className="col-md-8">{renderStepContent()}</div>
        <div className="col-md-4">
          <OrderSummary
            cartItems={cartItems}
            discountCode={discountCode}
            onDiscountCodeChange={handleDiscountCodeChange}
            onApplyDiscount={applyDiscount}
            totalAmount={totalAmount}
            shippingCost={shippingCharge}
            gstAmount={gstAmount}
            coupons={config.coupons}
            appliedCoupon={appliedCoupon}
            onRemoveCoupon={removeCoupon}
            promoCodeDiscount={promoCodeDiscount}
          />
        </div>
      </div>
    </div>
  );
}
