import React, { useState } from 'react';
import { Card, Row, Col, Button, Badge } from 'react-bootstrap';
import Shipping from '../checkout/Shipping';

export default function SavedAddress({savedAddresses, setSavedAddresses}) {
  const [showShipping, setShowShipping] = useState(false);

  const initialAddressState = {
    id:'',
    label: '',
    firstName: '',
    lastName: '',
    address: '',
    apartment: '',
    city: '',
    state: '',
    zip: '',
    phone: '',
  }
  
  const [shippingAddress, setShippingAddress] = useState(initialAddressState);

  const addNew = () => {
    setShowShipping(true);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setShippingAddress((prev) => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    
    setShowShipping(false);

    const newAddress = {
    id: Date.now(),
    label: shippingAddress.label,
    name: `${shippingAddress.firstName} ${shippingAddress.lastName}`,
    street: shippingAddress.address + (shippingAddress.apartment ? `, ${shippingAddress.apartment}` : ''),
    city: shippingAddress.city,
    state: shippingAddress.state,
    zip: shippingAddress.zip,
    country: 'India',
    phone: shippingAddress.phone,
  };

  console.log('New Address:', newAddress.name);

  setShippingAddress(initialAddressState);

  setSavedAddresses(prev => [...prev, newAddress]);
  };

  const handleCancel = () => {
    setShowShipping(false);
    setShippingAddress(initialAddressState);
  };

  return (
    <div style={{ maxWidth: 700, margin: '2rem auto' }}>
      {!showShipping && (
        <Button
          className="mb-3"
          variant="success"
          style={{ width: '100%', fontWeight: '600', fontSize: '1.1rem' }}
          onClick={addNew}
        >
          + Add a New Address
        </Button>
      )}

      {showShipping && (
        <Shipping
          shippingAddress={shippingAddress}
          onChange={handleChange}
          submitLabel="Save"
          cancelLabel="Cancel"
          onSubmit={handleSave}
          onCancel={handleCancel}
        />
      )}

      {!showShipping && (
        <>
          <div
            className="mb-4 text-secondary fw-semibold"
            style={{ letterSpacing: '0.1em', fontSize: '0.85rem' }}
          >
            {savedAddresses.length} SAVED ADDRESS{savedAddresses.length > 1 ? 'ES' : ''}
          </div>
          <hr />

          {savedAddresses.map((addr) => (
            <Card
              key={addr.id}
              className="mb-3 p-3 shadow-sm rounded-3 border"
              style={{ lineHeight: 1.4 }}
            >
              <Row>
                <Col md={9}>
                  <div className="d-flex align-items-center gap-2 mb-1">
                    {/* <h5 className="mb-0 fw-semibold" style={{ fontSize: '1.1rem' }}>
                      {addr.label}
                    </h5> */}
                    { addr.label && (
                      <Badge
                        bg={addr.label === 'default' ? 'primary' : 'secondary'}
                        className="text-uppercase small"
                        style={{
                          padding: '0.25em 0.5em',
                          fontWeight: '600',
                          letterSpacing: '0.05em',
                          borderRadius: '0.375rem',
                        }}
                      >
                        {addr.label === 'default' ? 'Default' : addr.label}
                      </Badge>
                    )}
                  </div>

                  <h2 className="mb-1" style={{ fontSize: '1.5rem' }}>
                    {addr.name || `${addr.firstname || ''} ${addr.lastname || ''}`}
                  </h2>
                  <p className="mb-1" style={{ fontSize: '1.5rem' }}>
                    {addr.address}, {addr.apartment}, {addr.city}, {addr.state} - {addr.zip}
                  </p>
                  <p className="mb-1" style={{ fontSize: '1.5rem' }}>
                    {addr.country}
                  </p>
                  <p className="mb-1" style={{ fontSize: '1.5rem' }}>
                    📞 {addr.phone}
                  </p>
                </Col>

                <Col
                  md={3}
                  className="d-flex flex-column justify-content-center align-items-end gap-2"
                >
                  <Button
                    variant="outline-primary"
                    size="sm"
                    className="rounded-pill w-100"
                    style={{
                      padding: '0.25rem 0.5rem',
                      fontSize: '0.85rem',
                      fontWeight: '600',
                      transition: 'all 0.3s ease',
                    }}
                  >
                    Edit
                  </Button>
                  <Button
                    variant="outline-danger"
                    size="sm"
                    className="rounded-pill w-100"
                    style={{
                      padding: '0.25rem 0.5rem',
                      fontSize: '0.85rem',
                      fontWeight: '600',
                      transition: 'all 0.3s ease',
                    }}
                  >
                    Delete
                  </Button>
                </Col>
              </Row>
            </Card>
          ))}
        </>
      )}
    </div>
  );
}
